class Device {
  static #nextId = 1;
  #ip;
  #lastSeen = null;

  constructor(name, ip) {
    this.id = Device.#nextId++;
    this.name = name;
    this.ip = ip;                      // runs the setter below
  }

  get ip() {
    return this.#ip;
  }

  set ip(value) {
    if (!/^\d{1,3}(\.\d{1,3}){3}$/.test(value)) throw new TypeError(`bad IPv4 address: ${value}`);
    this.#ip = value;
  }

  get label() {
    return `${this.name}@${this.#ip}`;
  }

  markSeen(when) {
    this.#lastSeen = when;
    return this;                       // returning this allows chaining
  }

  static fromLine(line) {
    const [name, ip] = line.split(',').map((s) => s.trim());
    return new Device(name, ip);
  }

  static isDevice(obj) {
    return #ip in obj;
  }

  toJSON() {
    return { id: this.id, name: this.name, ip: this.#ip };
  }
}

class Router extends Device {
  constructor(name, ip, wanIp) {
    super(name, ip);                   // must run before this is used
    this.wanIp = wanIp;
  }

  get label() {
    return `${super.label} (WAN ${this.wanIp})`;
  }
}

const pi = Device.fromLine(' pi, 192.168.1.50 ');
