async function getWithRetry(url, attempts = 3) {
  for (let i = 1; i <= attempts; i++) {
    const res = await fetch(url);
    if (res.ok) return res.json();
    if (res.status !== 503 && res.status !== 429) throw new Error(`HTTP ${res.status}, not retrying`);
    const wait = Number(res.headers.get('retry-after') ?? 1) * 1000;
    console.log(`attempt ${i}: ${res.status}, retrying in ${wait} ms`);
    if (i < attempts) await sleep(wait);
  }
  throw new Error(`gave up after ${attempts} attempts`);
}
