class Host {
  #ports = new Set();

  constructor(name, ip) {
    this.name = name;
    this.ip = ip;
  }

  open(port) {
    if (!Number.isInteger(port) || port < 1 || port > 65535) throw new RangeError(`invalid port: ${port}`);
    this.#ports.add(port);
    return this;
  }

  get openPorts() {
    return [...this.#ports].toSorted((a, b) => a - b);
  }

  toString() {
    return `${this.name} (${this.ip}): ${this.openPorts.join(', ')}`;
  }

  static parse(text) {
    const [name, ip, list = ''] = text.trim().split(/\s+/);
    const host = new Host(name, ip);
    for (const p of list.split(',').filter(Boolean)) host.open(Number(p));
    return host;
  }
}

console.log(String(Host.parse('pi 192.168.1.50 8080,22')));

